CREATE TABLE categoria(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre VARCHAR(80) NOT NULL UNIQUE,CHECK(TRIM(nombre)<>''));
CREATE TABLE producto(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,sku VARCHAR(32) NOT NULL UNIQUE,nombre VARCHAR(100) NOT NULL,precio NUMERIC(12,2) NOT NULL,categoria_id BIGINT NOT NULL REFERENCES categoria(id),version BIGINT NOT NULL DEFAULT 0,CHECK(precio>0),CHECK(TRIM(nombre)<>''),CHECK(sku=UPPER(sku) AND TRIM(sku)<>''));
